a=source_array().astype(float)
r,g,b=a[:,:,:3].transpose(2,0,1)
Y,X=np.indices((H,W))
# Pink printing, not warm stipple or opaque black lettering.
red=(r-g>65)&(r-b>45)&(r>130)&(a[:,:,3]>100)
red &= (Y>1003)&(X>125)&(X<1215)
red=clean_mask(red,sigma=.65,min_size=35,hole_size=8)
lab,n=ndi.label(red)
sizes=np.bincount(lab.ravel())
red=lab==(np.argmax(sizes[1:])+1)
# Continue the outer roll edges only behind the existing hoof silhouettes.
# These are structural closures; none add a visible crease to the artwork.
bridges=Image.new('L',(W,H),0)
draw=ImageDraw.Draw(bridges)
draw.line([(149,1071),(158,1063),(169,1055),(181,1047)],fill=255,width=7,joint='curve')
draw.line([(1134,1033),(1148,1037),(1161,1042),(1175,1048)],fill=255,width=7,joint='curve')
red |= np.asarray(bridges)>0
red=clean_mask(red,sigma=.95,min_size=30,hole_size=12)
# A single continuous paper surface. Its exact outer contour is shared with
# the pink drawing, so there are no mismatched overlapping face boundaries.
base=ndi.binary_fill_holes(red)
opts=dict(turdsize=20,alphamax=1.15,opttolerance=.55)
paper=mask_path(base,PALETTE['ivory'],**opts)
edges=mask_path(red,PALETTE['ribbon'],**opts)
body='<g id="motto-ribbon" aria-label="Continuous motto scroll"><g id="ribbon-paper-surface">'+paper+'</g><g id="ribbon-outline-and-curl-seams">'+edges+'</g></g>'+LETTERS
save_svg(ROOT/'components/ribbon.svg',body)
print('Rebuilt ribbon:',int(base.sum()),'surface pixels;',int(red.sum()),'pink edge pixels')
